// TH15 st03.ecl.txt:1454-1474 MainSub03 tail group.
// Closure: MainSub03b 1476-1535, ECir01 114-148 / ECir01_at 150-190,
//          GirlD01 841-865 / GirlD01_at 867-913.
// Card frame 0 opens the segment; source attack t=0 starts after OPENING_BUFFER.
const TIME_LIMIT: int = 1724;
const OPENING_BUFFER: int = 120;

const TH15_BALL: int = 416;        // source type4 (ECir01_at)
const TH15_RING_BALL2: int = 464;  // source type7 (GirlD01_at)

// st03.ecl.txt:867-913 GirlD01_at.
// etAim(0,9): aimed alternating-layer ring, 17 layers, H(q)=floor((q+1)/2)*delta,
// delta=0.02617994rad=273BAM, k=(q+1)&~1, v=s0+(s1-s0)*k/16.
// Layer sign reversal only reorders a full ring, so base=A+sign*H with a positive ring.
async sub girl_d01_at() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 10;
    if rank == 0 { n = 5; }
    var bursts: int = 6;
    if rank == 0 { bursts = 2; }
    else if rank == 1 { bursts = 4; }
    var s0: fx = 3.5fx;
    if rank <= 1 { s0 = 2.6fx; }
    else if rank == 2 { s0 = 3.2fx; }
    var s1: fx = 1.8fx;
    var iv: int = 90;
    if rank <= 1 { iv = 125; }
    for b in 0..bursts {
        var aim: angle = aim_player();
        for q in 0..17 {
            var h: int = ((q + 1) / 2) * 273;
            var dirsign: int = 1;
            if (q % 2) != 0 { dirsign = -1; }
            var k: int = ((q + 1) / 2) * 2;
            var v: fx = s0 + (s1 - s0) * k / 16;
            sh_reset(0);
            sh_sprite(0, TH15_RING_BALL2, 2);
            sh_aim(0, 0);
            sh_ring(0, 1);
            sh_count(0, n, 1);
            sh_angle(0, aim + ((dirsign * h) as angle), 0deg);
            sh_speed(0, v, 0fx);
            sh_dist(0, -4fx * v); // ANIM type2 a=1: position -= 4*velocity
            sh_fire(0);
        }
        wait(iv);
    }
}

// st03.ecl.txt:841-865 GirlD01.
async sub girl_d01() {
    set_invuln(65535);
    set_hurtbox(16fx); // setHurtbox(32,32): circle branch uses first*0.5
    set_hitbox(12fx);  // setHitbox(24,24)
    move_vel(0, 90deg, 2.5fx, EASE_LINEAR);     // moveVel(pi/2, 2.5)
    move_vel(70, 90deg, 0fx, EASE_QUAD_IN);     // moveVelTime(70, mode1, pi/2, 0)
    spawn girl_d01_at();
    wait(80);
    move_speed(120, 0.2fx, EASE_QUAD_IN);       // moveSpeedTime(120, mode1, 0.2)
    wait(400);
    move_speed(120, 3fx, EASE_QUAD_IN);         // moveSpeedTime(120, mode1, 3.0)
    loop { wait(1); }
}

// st03.ecl.txt:150-190 ECir01_at. etAim(0,3) ring of 1 path, base = player angle,
// speed 1.2 (E/N/H) or 2.0 (L); burst count rand(0/1 by RAND%2)/2/2/4; interval 70/50.
async sub ecir01_at() {
    wait(10);
    var rank: int = global(GVAR_RANK);
    var s: fx = 1.2fx;
    if rank >= 3 { s = 2.0fx; }
    var bursts: int = 2;
    if rank == 0 { bursts = rand(2); }
    if rank >= 3 { bursts = 4; }
    var iv: int = 70;
    if rank >= 3 { iv = 50; }
    for b in 0..bursts {
        var a: angle = aim_player();
        var px: fx = $self_x - 4fx * s * cos(a); // ANIM type2 a=1 retreat
        var py: fx = $self_y - 4fx * s * sin(a);
        _ = fire(TH15_BALL, 6, px, py, s, a, none, none);
        wait(iv);
    }
}

// st03.ecl.txt:114-148 ECir01.
async sub ecir01(sx: fx, sy: fx, tx: fx, ty: fx) {
    set_invuln(65535);
    set_hurtbox(12fx); // setHurtbox(24,24)
    set_hitbox(8fx);   // setHitbox(16,16)
    // movePosRel(RANDF2*16, RANDF2*16); movePosRelTime(60, mode1, 0, 0)
    var ox: fx = ((rand(65536) - 32768) as fx) / 2048fx;
    var oy: fx = ((rand(65536) - 32768) as fx) / 2048fx;
    move_to(0, sx + ox, sy + oy, EASE_LINEAR);
    move_to(60, sx, sy, EASE_QUAD_IN);
    wait(60);
    spawn ecir01_at();
    wait(60);
    // getAngle(FINAL -> F0,F1); moveVel(angle, 0); moveSpeedTime(120, mode0, 3.0)
    var ang: angle = atan2(ty - $self_y, tx - $self_x);
    move_vel(0, ang, 0fx, EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    loop { wait(1); }
}

// st03.ecl.txt:1476-1535 MainSub03b: 10 ECir01 per row, 40 px apart, every 10 frames.
sub cir_row(x0: fx, dx: fx, y: fx, tx: fx, ty: fx) {
    var x: fx = x0;
    for i in 0..10 {
        _ = spawn_enemy(x, y, 100, 0, 1000, 0, ecir01(x, y, tx, ty));
        x = x + dx;
        wait(10);
    }
}
// Rows inherit the F0/F1 target written just before each row in MainSub03b.
async sub cir_rows() {
    cir_row(180fx, -40fx, 64fx, -64fx, 320fx);  // F0=-64
    wait(60);
    cir_row(-180fx, 40fx, 140fx, 64fx, 320fx);  // F0=64
    wait(60);
    cir_row(180fx, -40fx, 180fx, 0fx, 320fx);   // F0=0
    wait(60);
    cir_row(-180fx, 40fx, 120fx, 0fx, 320fx);   // F0=0
}

// st03.ecl.txt:1454-1474 root schedule (B=1 -> one loop, then the 440 tail spawn).
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn cir_rows(); // 1454 async MainSub03b
    _ = spawn_enemy(96fx, -24fx, 1200, 0, 1000, 0, girl_d01);
    wait(220);
    _ = spawn_enemy(-96fx, -24fx, 1200, 0, 1000, 0, girl_d01);
    wait(220);
    _ = spawn_enemy(96fx, -24fx, 1200, 0, 1000, 0, girl_d01);
    wait(220);
    wait(220);
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(1); }
}
